// The full Twemoji set (CC-BY 4.0, see assets/emoji/LICENSE-GRAPHICS.txt) the player
// can place as marks. An emoji becomes an ordinary SVG mark when it is placed, drawn
// in its own colours or tinted like any other. Names and groups come from the
// unicode-emoji-json dataset (MIT), matched against the vendored Twemoji SVGs.
// People and hand gestures that support a skin tone list their five toned codes;
// the browser shows one neutral tile per emoji and a row of tone swatches that
// swaps in the toned artwork when placing.

export interface Emoji {
  code: string;
  char: string;
  name: string;
  group: string;
  /** Codes of the five toned variants (light to dark), when this emoji supports a skin tone. */
  tones?: string[];
}

export const EMOJI_GROUPS: [string, string][] = [
  ["smileys", "Smileys"],
  ["people", "People"],
  ["nature", "Nature"],
  ["food", "Food"],
  ["travel", "Travel"],
  ["activities", "Activities"],
  ["objects", "Objects"],
  ["symbols", "Symbols"],
  ["flags", "Flags"],
];

