export const emojiByChar = (char: string | undefined): Emoji | undefined => (char ? EMOJI.find((e) => e.char === char) : undefined);

// ------------------------------------------------------------------ lazy artwork

// Each SVG loads on demand rather than being bundled eagerly: with the full Twemoji
// set vendored (base emoji plus every skin-tone variant, a few thousand files) an
// eager glob would inline all of it into the renderer's main chunk. A lazy glob
// keeps each file its own chunk, fetched only once something asks to show it.
const URL_FILES = import.meta.glob<string>("../assets/emoji/*.svg", { query: "?url", import: "default" });
const RAW_FILES = import.meta.glob<string>("../assets/emoji/*.svg", { query: "?raw", import: "default" });

const urlCache = new Map<string, Promise<string>>();
const rawCache = new Map<string, Promise<string>>();

/** A URL for an <img>, suitable for showing the emoji in the UI. Resolves once loaded. */
export function emojiUrl(code: string): Promise<string> {
  let p = urlCache.get(code);
  if (!p) {
    const load = URL_FILES[`../assets/emoji/${code}.svg`];
    p = load ? load() : Promise.reject(new Error(`no emoji artwork for ${code}`));
    urlCache.set(code, p);
  }
  return p;
}

/** The raw SVG markup, for placing as a mark. Resolves once loaded. */
export function emojiRaw(code: string): Promise<string> {
  let p = rawCache.get(code);
  if (!p) {
    const load = RAW_FILES[`../assets/emoji/${code}.svg`];
    p = load ? load() : Promise.reject(new Error(`no emoji artwork for ${code}`));
    rawCache.set(code, p);
  }
  return p;
}

// ------------------------------------------------------------------ skin tones

export interface SkinTone {
  code: string;
  label: string;
  /** A swatch colour approximating the tone, for the picker row. */
  colour: string;
}

/** The five Fitzpatrick skin tone modifiers Twemoji draws, light to dark. */
export const SKIN_TONES: SkinTone[] = [
  { code: "1f3fb", label: "Light", colour: "#F5DAB3" },
  { code: "1f3fc", label: "Medium-light", colour: "#E0BB95" },
  { code: "1f3fd", label: "Medium", colour: "#BF8F68" },
  { code: "1f3fe", label: "Medium-dark", colour: "#9B643D" },
  { code: "1f3ff", label: "Dark", colour: "#5A3A22" },
];

/** The emoji's code for a chosen tone, or its own neutral code when it has none selected or does not support one. */
export function tonedCode(e: Emoji, tone: string | null): string {
  if (!tone || !e.tones) return e.code;
  const i = SKIN_TONES.findIndex((t) => t.code === tone);
  return e.tones[i] ?? e.code;
}
